const fs = require('node:fs');

// Loads the ENTIRE file into one string (after decoding the
// whole Buffer). For a 2GB log this is 2GB+ of heap — and the
// process cannot emit a single result until every byte is read.
const data = fs.readFileSync('access.log', 'utf8');

const counts = {};
for (const line of data.split('\n')) {
  const status = line.match(/"\s(\d{3})\s/)?.[1];
  if (status) counts[status] = (counts[status] ?? 0) + 1;
}

console.log(counts);

// Problems: memory scales with file size, first output waits
// for the whole read, and split() duplicates the string.

const fs = require('node:fs');
const { Transform } = require('node:stream');
const { pipeline } = require('node:stream/promises');

// A Transform that splits raw bytes into lines while keeping
// memory bounded to the highWaterMark (default 16KB).
const splitLines = new Transform({
  readableObjectMode: true,
  transform(chunk, encoding, callback) {
    const text = chunk.toString();
    this.lines = (this.lines ?? '') + text;
    const parts = this.lines.split('\n');
    this.lines = parts.pop(); // keep the partial tail
    for (const line of parts) this.push(line);
    callback();
  },
  flush(callback) {
    if (this.lines) this.push(this.lines);
    callback();
  }
});

async function main() {
  const counts = {};
  await pipeline(
    fs.createReadStream('access.log'),
    splitLines,
    async function* (source) {
      for await (const line of source) {
        const status = line.match(/"\s(\d{3})\s/)?.[1];
        if (status) counts[status] = (counts[status] ?? 0) + 1;
      }
    }
  );
  console.log(counts);
}

main().catch((err) => {
  console.error(err);
  process.exitCode = 1;
});
